import React, { useEffect, useState } from "react";
import { useNavigate } from "react-router-dom";
import { FiAward } from "react-icons/fi";

import DashboardLayout from "../../layouts/DashboardLayout";
import Card from "../../components/Card";
import FormField from "../../components/FormField";

import { gradeApi } from "../../api/gradeApi";
import { studentApi } from "../../api/studentApi";
import { registrationApi } from "../../api/registrationApi";

import { useLookupOptions } from "../../hooks/useLookupOptions";
import { useToast } from "../../context/ToastContext";
import { extractErrorMessage } from "../../api/axios";

import {
  validateFields,
  isRequired
} from "../../utils/validators";

import { fullName } from "../../utils/formatters";


// =====================================================
// GRADE OPTIONS
// =====================================================

const GRADE_OPTIONS = [
  "A",
  "A-",
  "B+",
  "B",
  "B-",
  "C+",
  "C",
  "C-",
  "D",
  "F"
].map((grade) => ({
  value: grade,
  label: grade
}));


// =====================================================
// INITIAL VALUES
// =====================================================

const initialValues = {
  student_id: "",
  registration_id: "",
  grade: "",
  remark: ""
};


// =====================================================
// COMPONENT
// =====================================================

export default function AssignGrade() {
  const navigate = useNavigate();
  const toast = useToast();

  const [values, setValues] = useState(initialValues);
  const [errors, setErrors] = useState({});

  const [isSubmitting, setIsSubmitting] = useState(false);

  const [registrationOptions, setRegistrationOptions] = useState([]);
  const [loadingRegistrations, setLoadingRegistrations] = useState(false);


  // =====================================================
  // LOAD STUDENTS
  // =====================================================

  const {
    options: studentOptions,
    isLoading: loadingStudents,
    error: studentError
  } = useLookupOptions(
    studentApi.getAll,

    (student) => {
      // Backend uses student_id
      const id =
        student.student_id ??
        student.id;

      if (!id) {
        return null;
      }

      const name = fullName(student);

      return {
        value: String(id),
        label: `${name}${
          student.registration_number
            ? ` — ${student.registration_number}`
            : ""
        }`
      };
    }
  );


  // =====================================================
  // LOAD STUDENT REGISTRATIONS
  // =====================================================

  useEffect(() => {
    let mounted = true;

    async function loadRegistrations() {
      // No student selected
      if (!values.student_id) {
        setRegistrationOptions([]);
        setLoadingRegistrations(false);
        return;
      }

      setLoadingRegistrations(true);
      setRegistrationOptions([]);

      try {
        console.log(
          "Loading registrations for student:",
          values.student_id
        );

        const response = await registrationApi.getByStudent(
          values.student_id
        );

        console.log(
          "Registration API response:",
          response
        );

        if (!mounted) return;

        /*
         * Axios normally returns:
         *
         * response.data
         *
         * Backend could return:
         *
         * {
         *   success: true,
         *   registrations: [...]
         * }
         *
         * or:
         *
         * {
         *   success: true,
         *   data: [...]
         * }
         *
         * or simply:
         *
         * [...]
         */

        const responseData = response?.data;

        let list = [];

        if (Array.isArray(responseData)) {
          list = responseData;
        } else if (Array.isArray(responseData?.registrations)) {
          list = responseData.registrations;
        } else if (Array.isArray(responseData?.data)) {
          list = responseData.data;
        } else if (Array.isArray(responseData?.items)) {
          list = responseData.items;
        } else if (Array.isArray(responseData?.courses)) {
          list = responseData.courses;
        }

        console.log(
          "Registration list:",
          list
        );


        // Convert registrations into select options
        const options = list
          .map((registration) => {

            // Backend registration ID
            const registrationId =
              registration.registration_id ??
              registration.id;

            if (!registrationId) {
              return null;
            }


            // Course code
            const courseCode =
              registration.course_code ??
              registration.course?.course_code ??
              registration.code ??
              registration.course?.code ??
              "";


            // Course name
            const courseName =
              registration.course_name ??
              registration.course?.course_name ??
              registration.name ??
              registration.course?.name ??
              "";


            // Semester
            const semester =
              registration.semester ??
              "";


            // Academic year
            const academicYear =
              registration.academic_year ??
              "";


            const courseTitle = [
              courseCode,
              courseName
            ]
              .filter(Boolean)
              .join(" — ");


            const semesterInfo = [
              semester,
              academicYear
            ]
              .filter(Boolean)
              .join(", ");


            const label =
              courseTitle && semesterInfo
                ? `${courseTitle} (${semesterInfo})`
                : courseTitle ||
                  semesterInfo ||
                  `Registration #${registrationId}`;


            return {
              value: String(registrationId),
              label
            };
          })
          .filter(Boolean);


        setRegistrationOptions(options);

      } catch (error) {

        console.error(
          "Failed to load student registrations:",
          error
        );

        if (!mounted) return;

        setRegistrationOptions([]);

        toast.error(
          extractErrorMessage(
            error,
            "Unable to load registered courses."
          )
        );

      } finally {

        if (mounted) {
          setLoadingRegistrations(false);
        }

      }
    }


    loadRegistrations();


    return () => {
      mounted = false;
    };

  }, [values.student_id, toast]);


  // =====================================================
  // HANDLE INPUT CHANGE
  // =====================================================

  function handleChange(e) {
    const {
      name,
      value
    } = e.target;


    setValues((previous) => ({
      ...previous,
      [name]: value,

      // When student changes, clear old registration
      ...(name === "student_id"
        ? {
            registration_id: ""
          }
        : {})
    }));


    setErrors((previous) => ({
      ...previous,
      [name]: ""
    }));
  }


  // =====================================================
  // HANDLE SUBMIT
  // =====================================================

  async function handleSubmit(e) {
    e.preventDefault();


    const fieldErrors = validateFields(
      values,
      {
        student_id: [isRequired],
        registration_id: [isRequired],
        grade: [isRequired]
      }
    );


    if (Object.keys(fieldErrors).length > 0) {
      setErrors(fieldErrors);

      toast.error(
        "Please complete all required fields."
      );

      return;
    }


    setIsSubmitting(true);


    try {

      await gradeApi.assign({
        student_id: Number(values.student_id),
        registration_id: Number(values.registration_id),
        grade: values.grade,
        remark: values.remark || ""
      });


      toast.success(
        "Grade assigned successfully."
      );


      navigate(
        `/grades/student/${values.student_id}`
      );

    } catch (error) {

      console.error(
        "Assign grade error:",
        error
      );

      toast.error(
        extractErrorMessage(
          error,
          "Unable to assign this grade."
        )
      );

    } finally {

      setIsSubmitting(false);

    }
  }


  // =====================================================
  // PAGE
  // =====================================================

  return (
    <DashboardLayout>

      <div className="max-w-lg mx-auto">

        {/* PAGE HEADER */}

        <div className="flex items-center gap-2 mb-6">

          <div className="h-9 w-9 rounded-lg bg-navy-100 text-navy-700 flex items-center justify-center">
            <FiAward size={16} />
          </div>

          <h1 className="font-display text-xl text-navy-800">
            Assign Grade
          </h1>

        </div>


        {/* STUDENT API ERROR */}

        {studentError && (
          <div className="mb-4 rounded-lg border border-red-200 bg-red-50 px-4 py-3 text-sm text-red-700">
            {studentError}
          </div>
        )}


        {/* FORM */}

        <Card className="p-6">

          <form
            onSubmit={handleSubmit}
            className="space-y-4"
            noValidate
          >

            {/* STUDENT */}

            <FormField
              as="select"
              label="Student"
              name="student_id"
              value={values.student_id}
              onChange={handleChange}
              error={errors.student_id}
              required
              options={studentOptions}
              placeholder={
                loadingStudents
                  ? "Loading students..."
                  : studentOptions.length === 0
                  ? "No students available"
                  : "Select a student"
              }
            />


            {/* COURSE REGISTRATION */}

            <FormField
              as="select"
              label="Course Registration"
              name="registration_id"
              value={values.registration_id}
              onChange={handleChange}
              error={errors.registration_id}
              required
              disabled={
                !values.student_id ||
                loadingRegistrations
              }
              options={registrationOptions}
              placeholder={
                !values.student_id
                  ? "Select a student first"
                  : loadingRegistrations
                  ? "Loading registered courses..."
                  : registrationOptions.length === 0
                  ? "No registered courses found"
                  : "Select a course registration"
              }
            />


            {/* GRADE */}

            <FormField
              as="select"
              label="Grade"
              name="grade"
              value={values.grade}
              onChange={handleChange}
              error={errors.grade}
              required
              options={GRADE_OPTIONS}
              placeholder="Select grade"
            />


            {/* REMARK */}

            <FormField
              as="textarea"
              label="Remark"
              name="remark"
              value={values.remark}
              onChange={handleChange}
              error={errors.remark}
              placeholder="Optional note about this grade"
            />


            {/* SUBMIT */}

            <button
              type="submit"
              disabled={
                isSubmitting ||
                loadingStudents ||
                loadingRegistrations ||
                !values.student_id ||
                !values.registration_id
              }
              className="w-full py-2.5 rounded-lg text-sm bg-navy-700 text-white hover:bg-navy-800 transition disabled:opacity-60"
            >
              {isSubmitting
                ? "Saving..."
                : "Assign Grade"}
            </button>

          </form>

        </Card>

      </div>

    </DashboardLayout>
  );
}
